"""Fail if the repository tracks game assets or build output.

    py -3 tools/check_no_game_assets.py          (also run by pytest)

Allowed binaries are listed explicitly: each is synthetic and carries no title
content. Anything else binary, and anything under a build directory, fails.
"""
import subprocess
import sys
from pathlib import PurePosixPath

ALLOWED = {
    "tools/conformance/test.xbe",            # generated by tools/conformance/mkxbe.py
    "tests/wma_decoder/fixtures/sine.wma",   # synthetic 440 Hz tone, CC0
}
BAD_EXT = {".xbe", ".xiso", ".iso", ".xpr", ".xip", ".xmv", ".wmv", ".wma", ".xbx",
           ".pdb", ".lib", ".obj", ".ilk", ".dll", ".exe", ".tlog", ".bin", ".dat"}
BAD_DIRS = {"build", "build-tooling", "game_files"}


def offenders(files):
    for f in files:
        p = PurePosixPath(f)
        if f in ALLOWED:
            continue
        if p.suffix.lower() in BAD_EXT or BAD_DIRS & set(p.parts[:-1]) or \
                any(part.startswith("build-") for part in p.parts[:-1]):
            yield f


def tracked():
    out = subprocess.run(["git", "ls-files"], capture_output=True, text=True, check=True).stdout
    return [l for l in out.splitlines() if l]


def test_no_game_assets_or_build_output():
    bad = list(offenders(tracked()))
    assert not bad, "tracked game assets / build output:\n  " + "\n  ".join(bad)


if __name__ == "__main__":
    bad = list(offenders(tracked()))
    for f in bad:
        print("tracked:", f)
    sys.exit(1 if bad else 0)
